/**
 * GlyphAtlas - Generate a texture atlas containing all ASCII glyphs
 * 
 * Creates a static texture with all printable ASCII characters (32-127)
 * rendered in a grid layout using a monospace font.
 */

/**
 * Generate a glyph atlas texture
 * @param {number} cellWidth - Width of each glyph cell in pixels
 * @param {number} cellHeight - Height of each glyph cell in pixels
 * @param {number} scale - Resolution scale factor (default: 4 for sharper rendering)
 * @returns {HTMLCanvasElement} Canvas containing the glyph atlas
 */
export function generateGlyphAtlas(cellWidth = 8, cellHeight = 16, scale = 4) {
  // ASCII printable range: 32-127 (96 glyphs)
  // Layout: 16 columns × 6 rows
  const cols = 16;
  const rows = 6;
  const atlasWidth = cols * cellWidth * scale;
  const atlasHeight = rows * cellHeight * scale;

  // Create canvas at higher resolution
  const canvas = document.createElement('canvas');
  canvas.width = atlasWidth;
  canvas.height = atlasHeight;
  const ctx = canvas.getContext('2d', { 
    willReadFrequently: false,
    alpha: true,
  });

  // Clear to black
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, atlasWidth, atlasHeight);

  // Font setup - use SF Mono (macOS system font)
  // Fallback to Menlo and Courier for compatibility
  const fontSize = Math.floor(cellHeight * scale * 0.85);
  ctx.font = `${fontSize}px "SF Mono", Menlo, "Courier New", monospace`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';
  
  // Enable better text rendering
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';

  // Render each glyph at higher resolution
  for (let i = 0; i < 96; i++) {
    const charCode = 32 + i; // Start from space (32)
    const char = String.fromCharCode(charCode);
    
    const col = i % cols;
    const row = Math.floor(i / cols);
    
    const x = (col * cellWidth + cellWidth / 2) * scale;
    const y = (row * cellHeight + cellHeight / 2) * scale;
    
    ctx.fillText(char, x, y);
  }

  return canvas;
}

/**
 * Get glyph atlas dimensions for a given cell size
 * @param {number} cellWidth - Width of each glyph cell
 * @param {number} cellHeight - Height of each glyph cell
 * @returns {Object} Atlas dimensions {width, height, cols, rows}
 */
export function getAtlasDimensions(cellWidth = 8, cellHeight = 16) {
  return {
    width: 16 * cellWidth,
    height: 6 * cellHeight,
    cols: 16,
    rows: 6,
  };
}
