/**
 * WebGL2Renderer - GPU-accelerated AAV1 frame renderer
 * 
 * Renders ASCII animation frames using WebGL2 with:
 * - One full-screen quad (2 triangles)
 * - One draw call per frame
 * - Two textures: glyph atlas (static) and cell data (dynamic)
 * - Zero CPU allocation per frame
 */

import vertexShaderSource from '../shaders/vertex.glsl?raw';
import fragmentShaderSource from '../shaders/fragment.glsl?raw';

export class WebGL2Renderer {
  /**
   * Initialize WebGL2 renderer
   * @param {HTMLCanvasElement} canvas - Target canvas element
   * @param {Object} metadata - AAV1 metadata from parser
   * @param {HTMLCanvasElement} glyphAtlas - Pre-rendered glyph atlas
   * @param {number} scale - Rendering scale factor (default: 4 for sharper rendering)
   * @param {Object} options - Optional rendering options
   * @param {number} options.width - Optional display width in pixels (overrides default)
   * @param {number} options.height - Optional display height in pixels (overrides default)
   */
  constructor(canvas, metadata, glyphAtlas, scale = 4, options = {}) {
    this.canvas = canvas;
    this.metadata = metadata;
    this.scale = scale;
    
    // Get WebGL2 context
    const gl = canvas.getContext('webgl2', {
      alpha: false,
      antialias: false,
      depth: false,
      stencil: false,
      premultipliedAlpha: false,
      preserveDrawingBuffer: true,
    });
    
    if (!gl) {
      throw new Error('WebGL2 not supported');
    }
    
    this.gl = gl;
    
    // Setup canvas size based on grid dimensions and cell size
    // Render at higher resolution for sharper text
    this.cellWidth = 8;
    this.cellHeight = 16;
    this.canvas.width = metadata.width * this.cellWidth * scale;
    this.canvas.height = metadata.height * this.cellHeight * scale;
    
    // Set CSS size to fill container (100% width and height)
    // Use optional width/height if provided for fixed sizing
    if (options.width !== undefined || options.height !== undefined) {
      // Fixed size mode
      if (options.width !== undefined) {
        this.canvas.style.width = `${options.width}px`;
      }
      if (options.height !== undefined) {
        this.canvas.style.height = `${options.height}px`;
      }
    } else {
      // Auto-fill container mode (default)
      this.canvas.style.width = '100%';
      this.canvas.style.height = '100%';
    }
    
    // Set viewport
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    
    // Initialize WebGL state
    this.initShaders();
    this.initGeometry();
    this.initTextures(glyphAtlas);
    this.initUniforms();
  }

  /**
   * Compile and link shaders
   */
  initShaders() {
    const gl = this.gl;
    
    // Compile vertex shader
    const vertexShader = this.compileShader(gl.VERTEX_SHADER, vertexShaderSource);
    
    // Compile fragment shader
    const fragmentShader = this.compileShader(gl.FRAGMENT_SHADER, fragmentShaderSource);
    
    // Link program
    const program = gl.createProgram();
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      const info = gl.getProgramInfoLog(program);
      throw new Error(`Failed to link program: ${info}`);
    }
    
    gl.useProgram(program);
    this.program = program;
    
    // Get attribute locations
    this.attribLocations = {
      position: gl.getAttribLocation(program, 'a_position'),
      uv: gl.getAttribLocation(program, 'a_uv'),
    };
    
    // Get uniform locations
    this.uniformLocations = {
      cellData: gl.getUniformLocation(program, 'u_cellData'),
      glyphAtlas: gl.getUniformLocation(program, 'u_glyphAtlas'),
      palette: gl.getUniformLocation(program, 'u_palette'),
      gridSize: gl.getUniformLocation(program, 'u_gridSize'),
      atlasGridSize: gl.getUniformLocation(program, 'u_atlasGridSize'),
    };
  }

  /**
   * Compile a shader
   * @param {number} type - Shader type (gl.VERTEX_SHADER or gl.FRAGMENT_SHADER)
   * @param {string} source - Shader source code
   * @returns {WebGLShader} Compiled shader
   */
  compileShader(type, source) {
    const gl = this.gl;
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      const info = gl.getShaderInfoLog(shader);
      const typeName = type === gl.VERTEX_SHADER ? 'vertex' : 'fragment';
      throw new Error(`Failed to compile ${typeName} shader: ${info}`);
    }
    
    return shader;
  }

  /**
   * Setup full-screen quad geometry
   */
  initGeometry() {
    const gl = this.gl;
    
    // Full-screen quad vertices (2 triangles)
    // Position (xy) and UV (uv)
    const vertices = new Float32Array([
      // Triangle 1
      -1.0, -1.0,  0.0, 0.0,  // Bottom-left
       1.0, -1.0,  1.0, 0.0,  // Bottom-right
      -1.0,  1.0,  0.0, 1.0,  // Top-left
      
      // Triangle 2
      -1.0,  1.0,  0.0, 1.0,  // Top-left
       1.0, -1.0,  1.0, 0.0,  // Bottom-right
       1.0,  1.0,  1.0, 1.0,  // Top-right
    ]);
    
    // Create and bind buffer
    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, vertices, gl.STATIC_DRAW);
    
    // Setup vertex attributes
    const stride = 4 * 4; // 4 floats * 4 bytes
    
    // Position attribute
    gl.enableVertexAttribArray(this.attribLocations.position);
    gl.vertexAttribPointer(
      this.attribLocations.position,
      2,           // 2 components (x, y)
      gl.FLOAT,
      false,
      stride,
      0            // offset
    );
    
    // UV attribute
    gl.enableVertexAttribArray(this.attribLocations.uv);
    gl.vertexAttribPointer(
      this.attribLocations.uv,
      2,           // 2 components (u, v)
      gl.FLOAT,
      false,
      stride,
      2 * 4        // offset: 2 floats * 4 bytes
    );
    
    this.vertexCount = 6;
  }

  /**
   * Initialize textures
   * @param {HTMLCanvasElement} glyphAtlas - Glyph atlas canvas
   */
  initTextures(glyphAtlas) {
    const gl = this.gl;
    
    // 1. Glyph atlas texture (static, RGBA8)
    this.glyphAtlasTexture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.glyphAtlasTexture);
    
    // Upload glyph atlas
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,                    // level
      gl.RGBA,              // internal format
      gl.RGBA,              // format
      gl.UNSIGNED_BYTE,     // type
      glyphAtlas            // source
    );
    
    // Linear filtering for smooth high-res atlas
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    
    // 2. Cell data texture (dynamic, RGBA8UI - unsigned integer)
    this.cellDataTexture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, this.cellDataTexture);
    
    // Allocate empty texture (will be updated per frame)
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,                    // level
      gl.RGBA8UI,           // internal format (unsigned integer)
      this.metadata.width,  // width
      this.metadata.height, // height
      0,                    // border
      gl.RGBA_INTEGER,      // format (integer)
      gl.UNSIGNED_BYTE,     // type
      null                  // data (allocate only)
    );
    
    // Nearest-neighbor filtering
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  }

  /**
   * Set uniform values
   */
  initUniforms() {
    const gl = this.gl;
    
    // Texture units
    gl.uniform1i(this.uniformLocations.glyphAtlas, 0);  // TEXTURE0
    gl.uniform1i(this.uniformLocations.cellData, 1);    // TEXTURE1
    
    // Grid size
    gl.uniform2f(
      this.uniformLocations.gridSize,
      this.metadata.width,
      this.metadata.height
    );
    
    // Atlas grid size (16 columns × 6 rows for ASCII 32-127)
    gl.uniform2f(this.uniformLocations.atlasGridSize, 16.0, 6.0);
    
    // Palette colors
    gl.uniform4fv(this.uniformLocations.palette, this.metadata.palette);
  }

  /**
   * Upload frame data to GPU
   * @param {Uint8Array} frameData - Frame cell data (width × height × 4 bytes)
   */
  uploadFrame(frameData) {
    const gl = this.gl;
    
    // Bind cell data texture
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, this.cellDataTexture);
    
    // Upload frame data (no CPU allocation!)
    gl.texSubImage2D(
      gl.TEXTURE_2D,
      0,                    // level
      0, 0,                 // xoffset, yoffset
      this.metadata.width,  // width
      this.metadata.height, // height
      gl.RGBA_INTEGER,      // format
      gl.UNSIGNED_BYTE,     // type
      frameData             // data (Uint8Array view)
    );
  }

  /**
   * Render the current frame
   */
  render() {
    const gl = this.gl;
    
    // Clear canvas
    gl.clearColor(0.0, 0.0, 0.0, 1.0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    
    // Draw full-screen quad (one draw call)
    gl.drawArrays(gl.TRIANGLES, 0, this.vertexCount);
  }

  /**
   * Cleanup resources
   */
  destroy() {
    const gl = this.gl;
    
    if (this.glyphAtlasTexture) {
      gl.deleteTexture(this.glyphAtlasTexture);
    }
    
    if (this.cellDataTexture) {
      gl.deleteTexture(this.cellDataTexture);
    }
    
    if (this.program) {
      gl.deleteProgram(this.program);
    }
  }
}
