import { useEffect, useRef, useState } from 'react';
import { AAV1Parser } from '../lib/aav1Parser.js';
import { generateGlyphAtlas } from '../lib/glyphAtlas.js';
import { WebGL2Renderer } from '../lib/webglRenderer.js';

/**
 * AAV1Player - Minimal React component for playing AAV1 animations
 * 
 * Automatically plays and loops the animation forever.
 * No controls, pure rendering.
 * 
 * @param {Object} props - Component props
 * @param {string} props.url - URL to the .aav1 animation file
 * @param {number} props.fps - Optional frames per second override
 * @param {number} props.width - Optional display width in pixels
 * @param {number} props.height - Optional display height in pixels
 */
export function AAV1Player({ url, fps, width, height }) {
  const canvasRef = useRef(null);
  const [status, setStatus] = useState('loading');
  const [error, setError] = useState(null);
  const [info, setInfo] = useState(null);

  useEffect(() => {
    let animationFrameId = null;
    let renderer = null;
    let parser = null;
    let startTime = null;
     let lastFrameIndex = -1;
     let disposed = false;

    const abortController = new AbortController();

    async function init() {
      try {
        setStatus('loading');
        
        // 1. Fetch .aav1 file (force reload from server, no cache)
        const response = await fetch(url, { cache: 'no-store', signal: abortController.signal });
        if (!response.ok) {
          throw new Error(`Failed to fetch ${url}: ${response.statusText}`);
        }
        
        const arrayBuffer = await response.arrayBuffer();
        if (disposed) return;
        
        // 2. Parse AAV1 file
        parser = new AAV1Parser(arrayBuffer);
        const metadata = parser.getMetadata();
        
        const requestedFps = typeof fps === 'number' ? fps : null;
        const rawPlaybackFps = requestedFps && requestedFps > 0 ? requestedFps : metadata.fps;
        const playbackFps = Number.isFinite(rawPlaybackFps) && rawPlaybackFps > 0 ? rawPlaybackFps : 24;
        
        setInfo({
          width: metadata.width,
          height: metadata.height,
          frameCount: metadata.frameCount,
          fps: playbackFps,
          duration: metadata.frameCount / playbackFps,
        });
        
        // 3. Generate glyph atlas at 4x resolution for sharper rendering
        const renderScale = 4;
        const glyphAtlas = generateGlyphAtlas(8, 16, renderScale);
        if (disposed) return;
        
        // 4. Initialize WebGL2 renderer with 4x scale
        if (!canvasRef.current) {
          throw new Error('Canvas element not available');
        }
        renderer = new WebGL2Renderer(canvasRef.current, metadata, glyphAtlas, renderScale, {
          width,
          height,
        });
        if (disposed) return;
        
        // 5. Render initial frame (frame 0)
        const initialFrameData = parser.getFrameData(0);
        renderer.uploadFrame(initialFrameData);
        renderer.render();
        lastFrameIndex = 0;
        if (disposed) return;
        
        // 6. Start animation loop (fixed timestep)
        startTime = performance.now();
        const frameDurationMs = 1000 / playbackFps;
        let nextFrameTime = startTime + frameDurationMs;

        setStatus('playing');

        function animate(now) {
          if (disposed || !parser || !renderer) return;

          if (now >= nextFrameTime) {
            const framesToAdvance = Math.max(
              1,
              Math.min(
                metadata.frameCount,
                Math.floor((now - nextFrameTime) / frameDurationMs) + 1,
              ),
            );

            lastFrameIndex = (lastFrameIndex + framesToAdvance) % metadata.frameCount;
            nextFrameTime += framesToAdvance * frameDurationMs;

            const frameData = parser.getFrameData(lastFrameIndex);
            renderer.uploadFrame(frameData);
            renderer.render();

          }

          if (!disposed) {
            animationFrameId = requestAnimationFrame(animate);
          }
        }
        
        // Start animation
        animationFrameId = requestAnimationFrame(animate);
        
      } catch (err) {
        if (disposed) return;
        if (err?.name === 'AbortError') return;

        setError(err instanceof Error ? err.message : String(err));
        setStatus('error');
      }
    }

    init();

    // Cleanup on unmount
    return () => {
      disposed = true;
      abortController.abort();

      if (animationFrameId !== null) {
        cancelAnimationFrame(animationFrameId);
        animationFrameId = null;
      }
      if (renderer) {
        renderer.destroy();
        renderer = null;
      }
      parser = null;
    };
  }, [url, fps, width, height]);

  return (
    <>
      {status === 'loading' && <div>Loading animation...</div>}
      {status === 'error' && <div style={{ color: 'red' }}>Error: {error}</div>}
      <canvas 
        ref={canvasRef}
        style={{
          imageRendering: 'auto',
          display: 'block',
        }}
      />
    </>
  );
}
