/**
 * AAV1Parser - Zero-copy parser for AAV1 animation files
 * 
 * Parses the binary AAV1 format once and provides views into frame data
 * without copying. All multi-byte integers are little-endian.
 */
export class AAV1Parser {
  /**
   * Parse an AAV1 file from an ArrayBuffer
   * @param {ArrayBuffer} arrayBuffer - The raw .aav1 file contents
   * @throws {Error} If the file is invalid or unsupported
   */
  constructor(arrayBuffer) {
    this.buffer = arrayBuffer;
    this.view = new DataView(arrayBuffer);
    this.byteArray = new Uint8Array(arrayBuffer);
    
    this.parseHeader();
    this.parsePalette();
    this.parseFrameIndex();
  }

  /**
   * Parse the 64-byte header
   */
  parseHeader() {
    // Magic number: "AAV1"
    const magic = String.fromCharCode(
      this.view.getUint8(0),
      this.view.getUint8(1),
      this.view.getUint8(2),
      this.view.getUint8(3)
    );
    
    if (magic !== 'AAV1') {
      throw new Error(`Invalid magic number: expected "AAV1", got "${magic}"`);
    }

    // Parse header fields (all little-endian)
    this.version = this.view.getUint16(4, true);
    this.width = this.view.getUint16(6, true);
    this.height = this.view.getUint16(8, true);
    this.frameCount = this.view.getUint32(10, true);
    this.fpsNum = this.view.getUint16(14, true);
    this.fpsDen = this.view.getUint16(16, true);
    this.flags = this.view.getUint32(18, true);
    this.paletteSize = this.view.getUint16(22, true);
    this.charEncoding = this.view.getUint16(24, true);


    // Compute FPS
    this.fps = this.fpsNum / this.fpsDen;

    // Validate
    if (this.version !== 1) {
      throw new Error(`Unsupported AAV1 version: ${this.version}`);
    }

    if (this.width === 0 || this.height === 0) {
      throw new Error(`Invalid dimensions: ${this.width}x${this.height}`);
    }

    if (this.frameCount === 0) {
      throw new Error('Frame count is zero');
    }

    // Frame payload size
    this.frameSize = this.width * this.height * 4;
  }

  /**
   * Parse the palette (paletteSize × 4 bytes RGBA)
   */
  parsePalette() {
    const paletteOffset = 64;
    this.palette = new Float32Array(this.paletteSize * 4);

    for (let i = 0; i < this.paletteSize; i++) {
      const offset = paletteOffset + i * 4;
      // Normalize to [0, 1] for GPU
      this.palette[i * 4 + 0] = this.view.getUint8(offset + 0) / 255.0; // R
      this.palette[i * 4 + 1] = this.view.getUint8(offset + 1) / 255.0; // G
      this.palette[i * 4 + 2] = this.view.getUint8(offset + 2) / 255.0; // B
      this.palette[i * 4 + 3] = this.view.getUint8(offset + 3) / 255.0; // A
    }
  }

  /**
   * Parse the frame index table (frameCount × 4 bytes)
   */
  parseFrameIndex() {
    const indexOffset = 64 + this.paletteSize * 4;
    this.frameOffsets = new Uint32Array(this.frameCount);

    for (let i = 0; i < this.frameCount; i++) {
      this.frameOffsets[i] = this.view.getUint32(indexOffset + i * 4, true);
    }
  }

  /**
   * Get a zero-copy view of frame data for a specific frame
   * @param {number} frameIndex - Frame index (0 to frameCount-1)
   * @returns {Uint8Array} View into the frame data (width × height × 4 bytes)
   */
  getFrameData(frameIndex) {
    if (frameIndex < 0 || frameIndex >= this.frameCount) {
      throw new Error(`Frame index out of bounds: ${frameIndex}`);
    }

    const offset = this.frameOffsets[frameIndex];
    
    // Return a view (no copy!)
    return new Uint8Array(this.buffer, offset, this.frameSize);
  }

  /**
   * Get metadata for the animation
   * @returns {Object} Metadata object
   */
  getMetadata() {
    return {
      version: this.version,
      width: this.width,
      height: this.height,
      frameCount: this.frameCount,
      fps: this.fps,
      fpsNum: this.fpsNum,
      fpsDen: this.fpsDen,
      flags: this.flags,
      paletteSize: this.paletteSize,
      charEncoding: this.charEncoding,
      palette: this.palette,
      duration: this.frameCount / this.fps,
    };
  }
}
